/** Deploy's closing lines: the build failed, or the live sites with their logins. */
function deployLines(result) {
  const { version } = result
  if (version.build_status === "failed")
    return [
      `The build of ${version.id} failed${version.build_error ? `: ${version.build_error}` : ""}. The previous version stays current.`,
      `Its log: atira eval status ${result.slug}`,
    ]
  return [
    `Version ${version.id} of ${result.slug} is ready${result.public ? " and public" : ""}; new runs use it.`,
    ...(result.preview?.status === "ready"
      ? ["", "Live:", ...previewLines(result.preview)]
      : result.preview
        ? [
            `The preview ${result.preview.status === "failed" ? `failed: ${result.preview.error ?? "no reason given"}` : `is ${result.preview.status}`}. atira eval preview ${result.slug} tries again.`,
          ]
        : []),
    "",
    `Run your agent on it: atira eval run ${result.slug} --package submission (or test, or a folder)`,
  ]
}

async function evalDeploy({ args, options, json }) {
  const ctx = context()
  const dir = args[0] ?? "."
  if (options["dry-run"]) {
    const bundle = buildEvalBundle(dir)
    return output(
      json,
      {
        dir: bundle.root,
        files: bundle.files.map((file) => file.path),
        bytes: bundle.gzip.length,
        manifest: bundle.manifest,
      },
      [
        `Valid. Would upload ${fileCount(bundle.files.length)}, ${size(bundle.gzip.length)} compressed:`,
        ...bundle.files.map((file) => `  ${file.path}  ${size(file.bytes.length)}`),
      ].join("\n"),
    )
  }
  const result = await deployEval(ctx, dir, {
    slug: options.slug,
    title: options.title,
    makePublic: options.public,
