text(await tools.exec_command({cmd:"python3 - <<'PY'
import json
from urllib.request import Request,urlopen
request=Request('https://ehl-challenge.atira.ai/openapi.json',headers={'User-Agent':'isar-labs-eval-infra-audit/1.0'})
with urlopen(request,timeout=15) as r:j=json.load(r)
for path,item in j.get('paths',{}).items():
 if 'eval-worlds/verify' in path:
  op=item['post'];print(json.dumps({'path':path,'summary':op.get('summary'),'description':op.get('description'),'request':op.get('requestBody'),'responses':op.get('responses')},indent=2))
PY","max_output_tokens":5000,"yield_time_ms":1000}));

