{
  "path": "/v1/eval-worlds/verify",
  "summary": "An eval world's app checks a login on one of its sites",
  "description": "Called by the eval's own app with its `ATIRA_EVAL_TOKEN`. Only logins of runs (`u_...`) and previews (`p_...`) on the token's version, the eval's current one, verify; anything else is 401. Rate-limited per token.",
  "request": {
    "required": true,
    "description": "The site's name and the login.",
    "content": {
      "application/json": {
        "schema": {
          "type": "object",
          "properties": {
            "site": {
              "type": "string"
            },
            "username": {
              "type": "string"
            },
            "password": {
              "type": "string"
            }
          },
          "required": [
            "site",
            "username",
            "password"
          ]
        }
      }
    }
  },
  "responses": {
    "200": {
      "description": "The run's or the preview's id, and when the login stops working",
      "content": {
        "application/json": {
          "schema": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "run_id": {
                    "type": "string"
                  },
                  "expires_at": {
                    "type": "integer",
                    "description": "Unix time in milliseconds"
                  }
                },
                "required": [
                  "run_id",
                  "expires_at"
                ]
              },
              {
                "type": "object",
                "properties": {
                  "preview_id": {
                    "type": "string"
                  },
                  "expires_at": {
                    "type": "integer",
                    "description": "Unix time in milliseconds"
                  }
                },
                "required": [
                  "preview_id",
                  "expires_at"
                ]
              }
            ]
          }
        }
      }
    },
    "400": {
      "$ref": "#/components/responses/Error400"
    },
    "401": {
      "$ref": "#/components/responses/Error401"
    },
    "429": {
      "$ref": "#/components/responses/Error429"
    }
  }
}

